export const MIGRATIONS: { name: string; sql: string }[] = [
  { name: "20261006000001_core_schema.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Esquema principal (multi-tenant)\n-- Cada registro de negócio pertence a uma organização (escritório).\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate extension if not exists \"pgcrypto\" with schema extensions;\ncreate extension if not exists \"unaccent\" with schema extensions;\ncreate extension if not exists \"pg_trgm\" with schema extensions;\n\n-- ─────────────────────────────── Tipos ───────────────────────────────\n\ncreate type public.app_role as enum ('admin', 'partner', 'lawyer', 'assistant', 'secretary');\n\ncreate type public.event_kind as enum (\n  'hearing',      -- Audiência\n  'deadline',     -- Prazo\n  'meeting',      -- Reunião\n  'diligence',    -- Diligência\n  'consultation', -- Consulta\n  'service',      -- Atendimento\n  'reminder',     -- Lembrete\n  'custom'        -- Evento personalizado\n);\n\ncreate type public.event_priority as enum ('low', 'medium', 'high', 'critical');\ncreate type public.event_status as enum ('scheduled', 'in_progress', 'done', 'cancelled', 'postponed');\ncreate type public.client_kind as enum ('individual', 'company');\ncreate type public.process_status as enum ('active', 'suspended', 'archived', 'closed', 'appeal');\ncreate type public.court_system as enum ('pje', 'esaj', 'projudi', 'eproc', 'tucujuris', 'other');\ncreate type public.calendar_provider as enum ('google', 'microsoft', 'caldav');\ncreate type public.notification_channel as enum ('in_app', 'push', 'email');\ncreate type public.suggestion_kind as enum ('hearing', 'deadline', 'reminder');\ncreate type public.suggestion_status as enum ('pending', 'accepted', 'dismissed');\n\n-- ─────────────────────────── Utilitários ────────────────────────────\n\ncreate or replace function public.set_updated_at()\nreturns trigger language plpgsql as $$\nbegin\n  new.updated_at := now();\n  return new;\nend $$;\n\n-- Normaliza texto para busca (sem acentos, minúsculas)\ncreate or replace function public.normalize_text(value text)\nreturns text language sql immutable parallel safe as $$\n  select lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(value, '')))\n$$;\n\n-- ─────────────────────────── Organizações ───────────────────────────\n\ncreate table public.organizations (\n  id uuid primary key default gen_random_uuid(),\n  name text not null check (char_length(name) between 2 and 160),\n  slug text not null unique,\n  document text,                         -- CNPJ do escritório\n  oab_registration text,                 -- Registro da sociedade na OAB\n  plan text not null default 'trial' check (plan in ('trial', 'solo', 'team', 'enterprise')),\n  trial_ends_at timestamptz default (now() + interval '14 days'),\n  settings jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table public.profiles (\n  id uuid primary key references auth.users (id) on delete cascade,\n  full_name text,\n  email text,\n  avatar_url text,\n  phone text,\n  oab_number text,\n  oab_state char(2),\n  timezone text not null default 'America/Sao_Paulo',\n  current_organization_id uuid references public.organizations (id) on delete set null,\n  preferences jsonb not null default '{\"defaultView\":\"timeGridWeek\",\"weekStartsOn\":0,\"defaultReminders\":[1440,60]}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table public.memberships (\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  user_id uuid not null references auth.users (id) on delete cascade,\n  role public.app_role not null default 'lawyer',\n  invited_by uuid references auth.users (id),\n  created_at timestamptz not null default now(),\n  primary key (organization_id, user_id)\n);\ncreate index memberships_user_idx on public.memberships (user_id);\n\ncreate table public.invitations (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  email text not null,\n  role public.app_role not null default 'lawyer',\n  token text not null unique default encode(extensions.gen_random_bytes(24), 'hex'),\n  invited_by uuid not null references auth.users (id),\n  accepted_at timestamptz,\n  expires_at timestamptz not null default (now() + interval '7 days'),\n  created_at timestamptz not null default now(),\n  unique (organization_id, email)\n);\n\n-- ──────────────────────── Categorias de eventos ──────────────────────\n\ncreate table public.event_categories (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  kind public.event_kind not null,\n  name text not null,\n  color text not null check (color ~ '^#[0-9A-Fa-f]{6}$'),\n  is_visible boolean not null default true,\n  position smallint not null default 0,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (organization_id, name)\n);\ncreate index event_categories_org_idx on public.event_categories (organization_id);\n\n-- ───────────────────────────── Clientes ──────────────────────────────\n\ncreate table public.clients (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  kind public.client_kind not null default 'individual',\n  name text not null check (char_length(name) between 2 and 200),\n  trade_name text,\n  document text,                        -- CPF ou CNPJ (somente dígitos)\n  rg text,\n  birth_date date,\n  email text,\n  phone text,\n  secondary_phone text,\n  address_zip text,\n  address_street text,\n  address_number text,\n  address_complement text,\n  address_district text,\n  address_city text,\n  address_state char(2),\n  notes text,\n  tags text[] not null default '{}',\n  responsible_id uuid references auth.users (id) on delete set null,\n  created_by uuid references auth.users (id) on delete set null,\n  archived_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  search tsvector generated always as (\n    setweight(to_tsvector('portuguese', coalesce(name, '')), 'A') ||\n    setweight(to_tsvector('portuguese', coalesce(trade_name, '')), 'A') ||\n    setweight(to_tsvector('simple', coalesce(document, '')), 'A') ||\n    setweight(to_tsvector('simple', coalesce(email, '')), 'B') ||\n    setweight(to_tsvector('portuguese', coalesce(notes, '')), 'C')\n  ) stored,\n  unique (organization_id, document)\n);\ncreate index clients_org_idx on public.clients (organization_id);\ncreate index clients_search_idx on public.clients using gin (search);\ncreate index clients_name_trgm_idx on public.clients using gin (name extensions.gin_trgm_ops);\n\n-- ───────────────────────────── Processos ─────────────────────────────\n\ncreate table public.processes (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  number text not null,                 -- Número CNJ: NNNNNNN-DD.AAAA.J.TR.OOOO\n  procedural_class text,                -- Classe processual\n  subject text,                         -- Assunto\n  tribunal text,                        -- Ex.: TJPA, TRT8, TRF1\n  court_division text,                  -- Vara / Órgão julgador\n  court_system public.court_system not null default 'pje',\n  instance smallint not null default 1 check (instance between 1 and 4),\n  client_id uuid references public.clients (id) on delete set null,\n  client_role text,                     -- Autor, Réu, Reclamante, ...\n  opposing_party text,\n  responsible_id uuid references auth.users (id) on delete set null,\n  status public.process_status not null default 'active',\n  claim_value numeric(14, 2),\n  distributed_at date,\n  last_movement_at timestamptz,\n  last_movement_summary text,\n  next_hearing_at timestamptz,\n  next_deadline_at timestamptz,\n  is_monitored boolean not null default true,\n  monitoring_checked_at timestamptz,\n  is_confidential boolean not null default false,  -- Segredo de justiça\n  tags text[] not null default '{}',\n  notes text,\n  created_by uuid references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  search tsvector generated always as (\n    setweight(to_tsvector('simple', coalesce(number, '')), 'A') ||\n    setweight(to_tsvector('simple', regexp_replace(coalesce(number, ''), '\\D', '', 'g')), 'A') ||\n    setweight(to_tsvector('portuguese', coalesce(procedural_class, '')), 'B') ||\n    setweight(to_tsvector('portuguese', coalesce(subject, '')), 'B') ||\n    setweight(to_tsvector('portuguese', coalesce(opposing_party, '')), 'B') ||\n    setweight(to_tsvector('simple', coalesce(tribunal, '')), 'C') ||\n    setweight(to_tsvector('portuguese', coalesce(court_division, '')), 'C') ||\n    setweight(to_tsvector('portuguese', coalesce(notes, '')), 'D')\n  ) stored,\n  unique (organization_id, number)\n);\ncreate index processes_org_idx on public.processes (organization_id);\ncreate index processes_client_idx on public.processes (client_id);\ncreate index processes_search_idx on public.processes using gin (search);\ncreate index processes_monitored_idx on public.processes (is_monitored, monitoring_checked_at) where is_monitored;\n\ncreate table public.process_movements (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  process_id uuid not null references public.processes (id) on delete cascade,\n  occurred_at timestamptz not null,\n  code integer,                         -- Código TPU/CNJ quando disponível\n  title text not null,\n  description text,\n  source text not null default 'manual', -- manual | datajud | pje | esaj | projudi | eproc\n  external_id text,\n  raw jsonb,\n  analyzed_at timestamptz,\n  created_at timestamptz not null default now(),\n  unique (process_id, source, external_id)\n);\ncreate index process_movements_process_idx on public.process_movements (process_id, occurred_at desc);\ncreate index process_movements_pending_idx on public.process_movements (analyzed_at) where analyzed_at is null;\n\n-- ────────────────────────────── Eventos ──────────────────────────────\n\ncreate table public.events (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  title text not null check (char_length(title) between 1 and 300),\n  kind public.event_kind not null default 'custom',\n  category_id uuid references public.event_categories (id) on delete set null,\n  description jsonb,                    -- Documento do editor rico (TipTap/ProseMirror JSON)\n  description_text text,                -- Texto plano para busca\n  starts_at timestamptz not null,\n  ends_at timestamptz not null,\n  all_day boolean not null default false,\n  timezone text not null default 'America/Sao_Paulo',\n  recurrence_rule text,                 -- RRULE (RFC 5545)\n  location text,\n  meeting_url text,\n  client_id uuid references public.clients (id) on delete set null,\n  process_id uuid references public.processes (id) on delete set null,\n  tribunal text,\n  court_division text,\n  responsible_id uuid references auth.users (id) on delete set null,\n  priority public.event_priority not null default 'medium',\n  status public.event_status not null default 'scheduled',\n  color text check (color is null or color ~ '^#[0-9A-Fa-f]{6}$'),\n  is_private boolean not null default false,\n  source text not null default 'lex',   -- lex | google | microsoft | caldav | ics | ai\n  created_by uuid references auth.users (id) on delete set null,\n  deleted_at timestamptz,               -- Exclusão lógica (lixeira)\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  search tsvector generated always as (\n    setweight(to_tsvector('portuguese', coalesce(title, '')), 'A') ||\n    setweight(to_tsvector('portuguese', coalesce(location, '')), 'B') ||\n    setweight(to_tsvector('portuguese', coalesce(tribunal, '') || ' ' || coalesce(court_division, '')), 'B') ||\n    setweight(to_tsvector('portuguese', coalesce(description_text, '')), 'C')\n  ) stored,\n  check (ends_at >= starts_at)\n);\ncreate index events_org_range_idx on public.events (organization_id, starts_at, ends_at) where deleted_at is null;\ncreate index events_process_idx on public.events (process_id);\ncreate index events_client_idx on public.events (client_id);\ncreate index events_responsible_idx on public.events (responsible_id, starts_at);\ncreate index events_search_idx on public.events using gin (search);\n\ncreate table public.event_checklist_items (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  event_id uuid not null references public.events (id) on delete cascade,\n  title text not null check (char_length(title) between 1 and 500),\n  is_done boolean not null default false,\n  position integer not null default 0,\n  due_at timestamptz,\n  done_at timestamptz,\n  done_by uuid references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index event_checklist_event_idx on public.event_checklist_items (event_id, position);\n\ncreate table public.event_reminders (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  event_id uuid not null references public.events (id) on delete cascade,\n  user_id uuid not null references auth.users (id) on delete cascade,\n  offset_minutes integer not null check (offset_minutes in (30, 60, 120, 1440, 4320, 10080, 21600, 43200) or offset_minutes between 0 and 525600),\n  channels public.notification_channel[] not null default '{in_app,push,email}',\n  remind_at timestamptz not null,\n  sent_at timestamptz,\n  created_at timestamptz not null default now(),\n  unique (event_id, user_id, offset_minutes)\n);\ncreate index event_reminders_due_idx on public.event_reminders (remind_at) where sent_at is null;\n\ncreate table public.event_attachments (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  event_id uuid references public.events (id) on delete cascade,\n  process_id uuid references public.processes (id) on delete cascade,\n  client_id uuid references public.clients (id) on delete cascade,\n  storage_path text not null unique,\n  file_name text not null,\n  mime_type text not null,\n  size_bytes bigint not null check (size_bytes > 0 and size_bytes <= 52428800),\n  uploaded_by uuid references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  check (num_nonnulls(event_id, process_id, client_id) >= 1)\n);\ncreate index event_attachments_event_idx on public.event_attachments (event_id);\n\ncreate table public.event_comments (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  event_id uuid not null references public.events (id) on delete cascade,\n  author_id uuid not null references auth.users (id) on delete cascade,\n  body text not null check (char_length(body) between 1 and 10000),\n  edited_at timestamptz,\n  created_at timestamptz not null default now()\n);\ncreate index event_comments_event_idx on public.event_comments (event_id, created_at);\n\n-- ─────────────────────── Histórico / Auditoria ───────────────────────\n\ncreate table public.activity_log (\n  id bigint generated always as identity primary key,\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  entity_type text not null,            -- event | client | process | checklist | attachment | comment\n  entity_id uuid not null,\n  parent_type text,\n  parent_id uuid,\n  action text not null,                 -- created | updated | deleted | completed | ...\n  actor_id uuid references auth.users (id) on delete set null,\n  changes jsonb,\n  created_at timestamptz not null default now()\n);\ncreate index activity_log_entity_idx on public.activity_log (entity_type, entity_id, created_at desc);\ncreate index activity_log_parent_idx on public.activity_log (parent_type, parent_id, created_at desc);\ncreate index activity_log_org_idx on public.activity_log (organization_id, created_at desc);\n\n-- ───────────────────────────── Notificações ──────────────────────────\n\ncreate table public.notifications (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  user_id uuid not null references auth.users (id) on delete cascade,\n  title text not null,\n  body text,\n  link text,\n  kind text not null default 'reminder',\n  read_at timestamptz,\n  created_at timestamptz not null default now()\n);\ncreate index notifications_user_idx on public.notifications (user_id, created_at desc);\n\ncreate table public.push_subscriptions (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references auth.users (id) on delete cascade,\n  endpoint text not null unique,\n  p256dh text not null,\n  auth text not null,\n  user_agent text,\n  created_at timestamptz not null default now()\n);\n\n-- ──────────────────────── Integrações de calendário ──────────────────\n\ncreate table public.calendar_connections (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  user_id uuid not null references auth.users (id) on delete cascade,\n  provider public.calendar_provider not null,\n  account_email text,\n  external_calendar_id text not null default 'primary',\n  -- Credenciais criptografadas (AES-256-GCM na aplicação). Nunca expostas ao cliente.\n  access_token_enc text,\n  refresh_token_enc text,\n  token_expires_at timestamptz,\n  caldav_url text,\n  caldav_username text,\n  caldav_password_enc text,\n  -- Estado de sincronização incremental\n  sync_token text,\n  webhook_channel_id text,\n  webhook_resource_id text,\n  webhook_expires_at timestamptz,\n  last_synced_at timestamptz,\n  last_error text,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (user_id, provider, external_calendar_id)\n);\n\ncreate table public.event_external_links (\n  event_id uuid not null references public.events (id) on delete cascade,\n  connection_id uuid not null references public.calendar_connections (id) on delete cascade,\n  external_id text not null,\n  etag text,\n  last_synced_at timestamptz not null default now(),\n  primary key (event_id, connection_id),\n  unique (connection_id, external_id)\n);\n\n-- ─────────────────── IA jurídica / Monitoramento ─────────────────────\n\ncreate table public.ai_suggestions (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  process_id uuid not null references public.processes (id) on delete cascade,\n  movement_id uuid references public.process_movements (id) on delete cascade,\n  kind public.suggestion_kind not null,\n  title text not null,\n  starts_at timestamptz,\n  ends_at timestamptz,\n  rationale text,\n  confidence numeric(3, 2) not null default 0.5 check (confidence between 0 and 1),\n  analyzer text not null default 'rules', -- rules | llm\n  payload jsonb not null default '{}'::jsonb,\n  status public.suggestion_status not null default 'pending',\n  event_id uuid references public.events (id) on delete set null,\n  decided_by uuid references auth.users (id) on delete set null,\n  decided_at timestamptz,\n  created_at timestamptz not null default now()\n);\ncreate index ai_suggestions_pending_idx on public.ai_suggestions (organization_id, status, created_at desc);\n\ncreate table public.court_credentials (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  user_id uuid not null references auth.users (id) on delete cascade,\n  court_system public.court_system not null,\n  tribunal text not null,\n  username text,\n  secret_enc text,\n  created_at timestamptz not null default now(),\n  unique (user_id, court_system, tribunal)\n);\n\n-- Certificado digital A1 (ICP-Brasil) — estrutura preparada para integração futura.\ncreate table public.digital_certificates (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  user_id uuid not null references auth.users (id) on delete cascade,\n  kind text not null default 'A1' check (kind in ('A1', 'A3')),\n  subject_name text,\n  subject_document text,\n  issuer text,\n  serial_number text,\n  valid_from timestamptz,\n  valid_until timestamptz,\n  storage_path text,                    -- PFX criptografado no bucket privado \"certificates\"\n  passphrase_enc text,\n  is_default boolean not null default false,\n  created_at timestamptz not null default now()\n);\n\n-- ───────────────────────── Triggers de updated_at ────────────────────\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['organizations','profiles','event_categories','clients','processes','events','event_checklist_items','calendar_connections']\n  loop\n    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', t);\n  end loop;\nend $$;\n" },
  { name: "20261006000002_security_rls.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Segurança: funções de autorização e Row Level Security\n--\n-- Matriz de papéis (resumo):\n--   admin      → tudo, inclusive equipe, faturamento e integrações da organização\n--   partner    → tudo do escritório, exceto gestão de faturamento\n--   lawyer     → cria/edita clientes, processos e eventos; exclui o que criou\n--   assistant  → cria/edita eventos, checklists e anexos; leitura de clientes/processos\n--   secretary  → agenda (eventos/lembretes) e cadastro de clientes; sem exclusões\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate or replace function public.is_member(org uuid)\nreturns boolean language sql stable security definer set search_path = '' as $$\n  select exists (\n    select 1 from public.memberships m\n    where m.organization_id = org and m.user_id = auth.uid()\n  )\n$$;\n\ncreate or replace function public.has_role(org uuid, roles public.app_role[])\nreturns boolean language sql stable security definer set search_path = '' as $$\n  select exists (\n    select 1 from public.memberships m\n    where m.organization_id = org and m.user_id = auth.uid() and m.role = any (roles)\n  )\n$$;\n\ncreate or replace function public.current_role_in(org uuid)\nreturns public.app_role language sql stable security definer set search_path = '' as $$\n  select m.role from public.memberships m where m.organization_id = org and m.user_id = auth.uid()\n$$;\n\n-- Ativa RLS em todas as tabelas públicas\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array[\n    'organizations','profiles','memberships','invitations','event_categories','clients','processes',\n    'process_movements','events','event_checklist_items','event_reminders','event_attachments',\n    'event_comments','activity_log','notifications','push_subscriptions','calendar_connections',\n    'event_external_links','ai_suggestions','court_credentials','digital_certificates'\n  ]\n  loop\n    execute format('alter table public.%I enable row level security', t);\n  end loop;\nend $$;\n\n-- ─────────────────────────── Organizações ───────────────────────────\ncreate policy \"membros leem a organização\" on public.organizations\n  for select using (public.is_member(id));\ncreate policy \"admin/sócio atualizam a organização\" on public.organizations\n  for update using (public.has_role(id, '{admin,partner}'));\n\n-- ───────────────────────────── Perfis ───────────────────────────────\ncreate policy \"usuário lê o próprio perfil e de colegas\" on public.profiles\n  for select using (\n    id = auth.uid() or exists (\n      select 1 from public.memberships a\n      join public.memberships b on a.organization_id = b.organization_id\n      where a.user_id = auth.uid() and b.user_id = profiles.id\n    )\n  );\ncreate policy \"usuário atualiza o próprio perfil\" on public.profiles\n  for update using (id = auth.uid()) with check (id = auth.uid());\n\n-- ──────────────────────────── Membros ───────────────────────────────\ncreate policy \"membros veem a equipe\" on public.memberships\n  for select using (public.is_member(organization_id));\ncreate policy \"admin gerencia equipe\" on public.memberships\n  for all using (public.has_role(organization_id, '{admin}'))\n  with check (public.has_role(organization_id, '{admin}'));\n\ncreate policy \"admin/sócio gerenciam convites\" on public.invitations\n  for all using (public.has_role(organization_id, '{admin,partner}'))\n  with check (public.has_role(organization_id, '{admin,partner}'));\n\n-- ─────────────────────────── Categorias ─────────────────────────────\ncreate policy \"membros leem categorias\" on public.event_categories\n  for select using (public.is_member(organization_id));\ncreate policy \"admin/sócio/advogado gerenciam categorias\" on public.event_categories\n  for all using (public.has_role(organization_id, '{admin,partner,lawyer}'))\n  with check (public.has_role(organization_id, '{admin,partner,lawyer}'));\n\n-- ─────────────────────────── Clientes ───────────────────────────────\ncreate policy \"membros leem clientes\" on public.clients\n  for select using (public.is_member(organization_id));\ncreate policy \"cadastro de clientes\" on public.clients\n  for insert with check (public.has_role(organization_id, '{admin,partner,lawyer,secretary}'));\ncreate policy \"edição de clientes\" on public.clients\n  for update using (public.has_role(organization_id, '{admin,partner,lawyer,secretary}'));\ncreate policy \"exclusão de clientes\" on public.clients\n  for delete using (public.has_role(organization_id, '{admin,partner}'));\n\n-- ─────────────────────────── Processos ──────────────────────────────\ncreate policy \"membros leem processos\" on public.processes\n  for select using (\n    public.is_member(organization_id)\n    and (not is_confidential or public.has_role(organization_id, '{admin,partner}') or responsible_id = auth.uid())\n  );\ncreate policy \"cadastro de processos\" on public.processes\n  for insert with check (public.has_role(organization_id, '{admin,partner,lawyer}'));\ncreate policy \"edição de processos\" on public.processes\n  for update using (public.has_role(organization_id, '{admin,partner,lawyer,assistant}'));\ncreate policy \"exclusão de processos\" on public.processes\n  for delete using (\n    public.has_role(organization_id, '{admin,partner}')\n    or (public.has_role(organization_id, '{lawyer}') and created_by = auth.uid())\n  );\n\ncreate policy \"membros leem movimentações\" on public.process_movements\n  for select using (public.is_member(organization_id));\ncreate policy \"registro de movimentações\" on public.process_movements\n  for insert with check (public.has_role(organization_id, '{admin,partner,lawyer,assistant}'));\ncreate policy \"exclusão de movimentações\" on public.process_movements\n  for delete using (public.has_role(organization_id, '{admin,partner,lawyer}'));\n\n-- ──────────────────────────── Eventos ───────────────────────────────\ncreate policy \"membros leem eventos\" on public.events\n  for select using (\n    public.is_member(organization_id)\n    and (not is_private or created_by = auth.uid() or responsible_id = auth.uid())\n  );\ncreate policy \"criação de eventos\" on public.events\n  for insert with check (public.is_member(organization_id));\ncreate policy \"edição de eventos\" on public.events\n  for update using (\n    public.is_member(organization_id)\n    and (not is_private or created_by = auth.uid() or responsible_id = auth.uid())\n  );\ncreate policy \"exclusão de eventos\" on public.events\n  for delete using (\n    public.has_role(organization_id, '{admin,partner}')\n    or (public.has_role(organization_id, '{lawyer,assistant}') and (created_by = auth.uid() or responsible_id = auth.uid()))\n  );\n\n-- Recursos internos do evento: qualquer membro que enxerga o evento\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['event_checklist_items','event_attachments']\n  loop\n    execute format($f$\n      create policy \"membros acessam %1$s\" on public.%1$I\n        for select using (public.is_member(organization_id));\n      create policy \"membros criam %1$s\" on public.%1$I\n        for insert with check (public.is_member(organization_id));\n      create policy \"membros editam %1$s\" on public.%1$I\n        for update using (public.is_member(organization_id));\n      create policy \"membros removem %1$s\" on public.%1$I\n        for delete using (public.has_role(organization_id, '{admin,partner,lawyer,assistant}'));\n    $f$, t);\n  end loop;\nend $$;\n\ncreate policy \"lembretes: dono lê\" on public.event_reminders\n  for select using (user_id = auth.uid() or public.has_role(organization_id, '{admin}'));\ncreate policy \"lembretes: dono gerencia\" on public.event_reminders\n  for all using (user_id = auth.uid() and public.is_member(organization_id))\n  with check (user_id = auth.uid() and public.is_member(organization_id));\n\ncreate policy \"comentários: membros leem\" on public.event_comments\n  for select using (public.is_member(organization_id));\ncreate policy \"comentários: membros escrevem\" on public.event_comments\n  for insert with check (public.is_member(organization_id) and author_id = auth.uid());\ncreate policy \"comentários: autor edita\" on public.event_comments\n  for update using (author_id = auth.uid());\ncreate policy \"comentários: autor ou admin remove\" on public.event_comments\n  for delete using (author_id = auth.uid() or public.has_role(organization_id, '{admin,partner}'));\n\ncreate policy \"histórico: membros leem\" on public.activity_log\n  for select using (public.is_member(organization_id));\n\n-- ─────────────────────────── Notificações ───────────────────────────\ncreate policy \"notificações do próprio usuário\" on public.notifications\n  for select using (user_id = auth.uid());\ncreate policy \"marcar notificações como lidas\" on public.notifications\n  for update using (user_id = auth.uid()) with check (user_id = auth.uid());\ncreate policy \"remover notificações\" on public.notifications\n  for delete using (user_id = auth.uid());\n\ncreate policy \"push: próprio usuário\" on public.push_subscriptions\n  for all using (user_id = auth.uid()) with check (user_id = auth.uid());\n\n-- ─────────────────────────── Integrações ────────────────────────────\n-- Tokens ficam acessíveis apenas ao service role. O cliente enxerga só metadados via view.\ncreate policy \"conexões: dono remove\" on public.calendar_connections\n  for delete using (user_id = auth.uid());\n\ncreate view public.calendar_connections_public with (security_invoker = true) as\n  select id, organization_id, user_id, provider, account_email, external_calendar_id,\n         last_synced_at, last_error, is_active, created_at\n  from public.calendar_connections;\n\ncreate policy \"conexões: dono lê metadados\" on public.calendar_connections\n  for select using (user_id = auth.uid());\n-- Permissões em nível de coluna: o papel authenticated nunca lê os segredos criptografados.\nrevoke select, insert, update on public.calendar_connections from authenticated, anon;\ngrant select (id, organization_id, user_id, provider, account_email, external_calendar_id, token_expires_at,\n              caldav_url, caldav_username, last_synced_at, last_error, is_active, created_at, updated_at)\n  on public.calendar_connections to authenticated;\n\ncreate policy \"vínculos externos: membros leem\" on public.event_external_links\n  for select using (exists (select 1 from public.events e where e.id = event_id and public.is_member(e.organization_id)));\n\n-- ──────────────────────────── IA / Monitoramento ────────────────────\ncreate policy \"sugestões: membros leem\" on public.ai_suggestions\n  for select using (public.is_member(organization_id));\ncreate policy \"sugestões: membros decidem\" on public.ai_suggestions\n  for update using (public.has_role(organization_id, '{admin,partner,lawyer,assistant}'));\n\ncreate policy \"credenciais de tribunal: dono\" on public.court_credentials\n  for all using (user_id = auth.uid()) with check (user_id = auth.uid() and public.is_member(organization_id));\nrevoke select, update on public.court_credentials from authenticated, anon;\ngrant select (id, organization_id, user_id, court_system, tribunal, username, created_at) on public.court_credentials to authenticated;\n\ncreate policy \"certificados: dono\" on public.digital_certificates\n  for all using (user_id = auth.uid()) with check (user_id = auth.uid() and public.is_member(organization_id));\nrevoke select, update on public.digital_certificates from authenticated, anon;\ngrant select (id, organization_id, user_id, kind, subject_name, subject_document, issuer, serial_number,\n              valid_from, valid_until, storage_path, is_default, created_at)\n  on public.digital_certificates to authenticated;\n\n-- ───────────────────────────── Storage ──────────────────────────────\n-- Caminho dos arquivos: {organization_id}/{entity}/{entity_id}/{uuid}-{nome}\ninsert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nvalues\n  ('attachments', 'attachments', false, 52428800, array[\n    'application/pdf',\n    'application/msword',\n    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',\n    'application/vnd.ms-excel',\n    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',\n    'application/vnd.ms-powerpoint',\n    'application/vnd.openxmlformats-officedocument.presentationml.presentation',\n    'application/vnd.oasis.opendocument.text',\n    'application/rtf', 'text/plain', 'text/csv', 'text/calendar',\n    'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/gif',\n    'audio/mpeg', 'audio/mp4', 'video/mp4',\n    'application/zip', 'application/x-zip-compressed',\n    'message/rfc822', 'application/vnd.ms-outlook'\n  ]),\n  ('certificates', 'certificates', false, 1048576, array['application/x-pkcs12']),\n  ('avatars', 'avatars', true, 2097152, array['image/png', 'image/jpeg', 'image/webp'])\non conflict (id) do nothing;\n\ncreate policy \"anexos: membros leem\" on storage.objects\n  for select to authenticated\n  using (bucket_id = 'attachments' and public.is_member(((storage.foldername(name))[1])::uuid));\ncreate policy \"anexos: membros enviam\" on storage.objects\n  for insert to authenticated\n  with check (bucket_id = 'attachments' and public.is_member(((storage.foldername(name))[1])::uuid));\ncreate policy \"anexos: equipe jurídica remove\" on storage.objects\n  for delete to authenticated\n  using (bucket_id = 'attachments' and public.has_role(((storage.foldername(name))[1])::uuid, '{admin,partner,lawyer,assistant}'));\n\ncreate policy \"certificados: somente o dono\" on storage.objects\n  for all to authenticated\n  using (bucket_id = 'certificates' and (storage.foldername(name))[2] = auth.uid()::text)\n  with check (bucket_id = 'certificates' and (storage.foldername(name))[2] = auth.uid()::text);\n\ncreate policy \"avatares: leitura pública\" on storage.objects\n  for select using (bucket_id = 'avatars');\ncreate policy \"avatares: dono envia\" on storage.objects\n  for insert to authenticated\n  with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);\ncreate policy \"avatares: dono atualiza\" on storage.objects\n  for update to authenticated\n  using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);\n" },
  { name: "20261006000003_functions_triggers.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Regras de negócio no banco: onboarding, lembretes,\n-- histórico, agregados de processos e busca global.\n-- ════════════════════════════════════════════════════════════════════════════\n\n-- ───────────────────── Categorias padrão do escritório ─────────────────────\ncreate or replace function public.seed_default_categories(org uuid)\nreturns void language sql security definer set search_path = '' as $$\n  insert into public.event_categories (organization_id, kind, name, color, position) values\n    (org, 'hearing',      'Audiência',          '#D93F3F', 0),\n    (org, 'deadline',     'Prazo',              '#E8833A', 1),\n    (org, 'meeting',      'Reunião',            '#3478F6', 2),\n    (org, 'diligence',    'Diligência',         '#8E5BD9', 3),\n    (org, 'consultation', 'Consulta',           '#2BA59A', 4),\n    (org, 'service',      'Atendimento',        '#556B2F', 5),\n    (org, 'reminder',     'Lembrete',           '#E5B800', 6),\n    (org, 'custom',       'Evento personalizado','#8E8E93', 7)\n  on conflict (organization_id, name) do nothing\n$$;\n\n-- ───────────────────── Onboarding: novo usuário ─────────────────────\n-- Cria perfil; se houver convite pendente, entra na organização convidante;\n-- caso contrário, cria um escritório próprio com o usuário como administrador.\ncreate or replace function public.handle_new_user()\nreturns trigger language plpgsql security definer set search_path = '' as $$\ndeclare\n  org_id uuid;\n  invite record;\n  display_name text := coalesce(\n    new.raw_user_meta_data ->> 'full_name',\n    new.raw_user_meta_data ->> 'name',\n    split_part(new.email, '@', 1)\n  );\nbegin\n  select * into invite from public.invitations\n   where lower(email) = lower(new.email) and accepted_at is null and expires_at > now()\n   order by created_at desc limit 1;\n\n  if invite.id is not null then\n    org_id := invite.organization_id;\n    insert into public.memberships (organization_id, user_id, role, invited_by)\n    values (org_id, new.id, invite.role, invite.invited_by);\n    update public.invitations set accepted_at = now() where id = invite.id;\n  else\n    insert into public.organizations (name, slug)\n    values (\n      coalesce(new.raw_user_meta_data ->> 'organization_name', 'Escritório de ' || display_name),\n      lower(regexp_replace(public.normalize_text(display_name), '[^a-z0-9]+', '-', 'g')) || '-' || substr(new.id::text, 1, 6)\n    )\n    returning id into org_id;\n    insert into public.memberships (organization_id, user_id, role) values (org_id, new.id, 'admin');\n    perform public.seed_default_categories(org_id);\n  end if;\n\n  insert into public.profiles (id, full_name, email, avatar_url, current_organization_id)\n  values (new.id, display_name, new.email, new.raw_user_meta_data ->> 'avatar_url', org_id);\n\n  return new;\nend $$;\n\ncreate trigger on_auth_user_created\n  after insert on auth.users\n  for each row execute function public.handle_new_user();\n\n-- ───────────── Preenche organization_id dos filhos a partir do evento ─────────────\ncreate or replace function public.inherit_event_org()\nreturns trigger language plpgsql security definer set search_path = '' as $$\nbegin\n  if new.event_id is not null then\n    select organization_id into new.organization_id from public.events where id = new.event_id;\n  end if;\n  return new;\nend $$;\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['event_checklist_items','event_reminders','event_comments']\n  loop\n    execute format('create trigger inherit_org before insert on public.%I for each row execute function public.inherit_event_org()', t);\n  end loop;\nend $$;\n\ncreate trigger inherit_org before insert on public.event_attachments\n  for each row when (new.event_id is not null) execute function public.inherit_event_org();\n\n-- ───────────────────────── Lembretes ─────────────────────────\ncreate or replace function public.compute_reminder_time()\nreturns trigger language plpgsql security definer set search_path = '' as $$\nbegin\n  select e.starts_at - make_interval(mins => new.offset_minutes)\n    into new.remind_at\n    from public.events e where e.id = new.event_id;\n  return new;\nend $$;\n\ncreate trigger compute_reminder_time\n  before insert or update of offset_minutes on public.event_reminders\n  for each row execute function public.compute_reminder_time();\n\n-- Ao remarcar o evento, reagenda lembretes não enviados (e reabre os futuros)\ncreate or replace function public.reschedule_reminders()\nreturns trigger language plpgsql security definer set search_path = '' as $$\nbegin\n  if new.starts_at is distinct from old.starts_at then\n    update public.event_reminders\n       set remind_at = new.starts_at - make_interval(mins => offset_minutes),\n           sent_at = case when new.starts_at - make_interval(mins => offset_minutes) > now() then null else sent_at end\n     where event_id = new.id;\n  end if;\n  return new;\nend $$;\n\ncreate trigger reschedule_reminders\n  after update of starts_at on public.events\n  for each row execute function public.reschedule_reminders();\n\n-- ───────────────────── Agregados do processo ─────────────────────\n-- Mantém \"próxima audiência\" e \"próximo prazo\" atualizados a partir da agenda.\ncreate or replace function public.refresh_process_schedule(pid uuid)\nreturns void language sql security definer set search_path = '' as $$\n  update public.processes p set\n    next_hearing_at = (\n      select min(e.starts_at) from public.events e\n      where e.process_id = pid and e.kind = 'hearing' and e.deleted_at is null\n        and e.status not in ('cancelled', 'done') and e.starts_at >= now()\n    ),\n    next_deadline_at = (\n      select min(e.starts_at) from public.events e\n      where e.process_id = pid and e.kind = 'deadline' and e.deleted_at is null\n        and e.status not in ('cancelled', 'done') and e.starts_at >= now() - interval '1 day'\n    )\n  where p.id = pid\n$$;\n\ncreate or replace function public.on_event_change_refresh_process()\nreturns trigger language plpgsql security definer set search_path = '' as $$\nbegin\n  if tg_op in ('INSERT', 'UPDATE') and new.process_id is not null then\n    perform public.refresh_process_schedule(new.process_id);\n  end if;\n  if tg_op in ('UPDATE', 'DELETE') and old.process_id is not null\n     and (tg_op = 'DELETE' or old.process_id is distinct from new.process_id) then\n    perform public.refresh_process_schedule(old.process_id);\n  end if;\n  return null;\nend $$;\n\ncreate trigger refresh_process_schedule\n  after insert or update or delete on public.events\n  for each row execute function public.on_event_change_refresh_process();\n\ncreate or replace function public.on_movement_insert()\nreturns trigger language plpgsql security definer set search_path = '' as $$\nbegin\n  update public.processes\n     set last_movement_at = new.occurred_at,\n         last_movement_summary = new.title\n   where id = new.process_id\n     and (last_movement_at is null or last_movement_at <= new.occurred_at);\n  return new;\nend $$;\n\ncreate trigger on_movement_insert\n  after insert on public.process_movements\n  for each row execute function public.on_movement_insert();\n\n-- ───────────────────────── Histórico de atividades ─────────────────────────\ncreate or replace function public.log_activity()\nreturns trigger language plpgsql security definer set search_path = '' as $$\ndeclare\n  rec jsonb;\n  old_rec jsonb;\n  diff jsonb := '{}'::jsonb;\n  k text;\n  act text;\n  p_type text;\n  p_id uuid;\n  ignored text[] := array['updated_at', 'search', 'description'];\nbegin\n  rec := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;\n  -- Exclusão em cascata da organização: não há onde registrar\n  if not exists (select 1 from public.organizations o where o.id = (rec ->> 'organization_id')::uuid) then\n    return null;\n  end if;\n  act := lower(tg_op) || 'd';\n  if tg_op = 'UPDATE' then\n    old_rec := to_jsonb(old);\n    for k in select jsonb_object_keys(rec) loop\n      if not (k = any (ignored)) and rec -> k is distinct from old_rec -> k then\n        diff := diff || jsonb_build_object(k, jsonb_build_object('from', old_rec -> k, 'to', rec -> k));\n      end if;\n    end loop;\n    if diff = '{}'::jsonb then\n      if rec -> 'description' is distinct from old_rec -> 'description' then\n        diff := jsonb_build_object('description', jsonb_build_object('changed', true));\n      else\n        return null;\n      end if;\n    end if;\n    if tg_table_name = 'event_checklist_items' and diff ? 'is_done' then\n      act := case when (rec ->> 'is_done')::boolean then 'completed' else 'reopened' end;\n    end if;\n    if tg_table_name = 'events' and diff ? 'deleted_at' then\n      act := case when rec ->> 'deleted_at' is null then 'restored' else 'trashed' end;\n    end if;\n  elsif tg_op = 'INSERT' then\n    diff := null;\n  end if;\n\n  if tg_table_name in ('event_checklist_items', 'event_attachments', 'event_comments') and rec ? 'event_id' and rec ->> 'event_id' is not null then\n    p_type := 'event'; p_id := (rec ->> 'event_id')::uuid;\n  elsif tg_table_name = 'processes' and rec ->> 'client_id' is not null then\n    p_type := 'client'; p_id := (rec ->> 'client_id')::uuid;\n  elsif tg_table_name = 'events' and rec ->> 'process_id' is not null then\n    p_type := 'process'; p_id := (rec ->> 'process_id')::uuid;\n  end if;\n\n  insert into public.activity_log (organization_id, entity_type, entity_id, parent_type, parent_id, action, actor_id, changes)\n  values (\n    (rec ->> 'organization_id')::uuid,\n    case tg_table_name\n      when 'events' then 'event' when 'clients' then 'client' when 'processes' then 'process'\n      when 'event_checklist_items' then 'checklist' when 'event_attachments' then 'attachment'\n      when 'event_comments' then 'comment' else tg_table_name end,\n    (rec ->> 'id')::uuid, p_type, p_id, act, auth.uid(), diff\n  );\n  return null;\nend $$;\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['events','clients','processes','event_checklist_items','event_attachments','event_comments']\n  loop\n    execute format('create trigger log_activity after insert or update or delete on public.%I for each row execute function public.log_activity()', t);\n  end loop;\nend $$;\n\n-- ─────────────────────────── Busca global ───────────────────────────\ncreate or replace function public.global_search(org uuid, q text, max_results int default 8)\nreturns table (\n  entity_type text,\n  id uuid,\n  title text,\n  subtitle text,\n  starts_at timestamptz,\n  rank real\n) language sql stable security invoker set search_path = public, extensions as $$\n  with query as (\n    select websearch_to_tsquery('portuguese', q) as tsq,\n           '%' || public.normalize_text(q) || '%' as pattern,\n           regexp_replace(q, '\\D', '', 'g') as digits\n  )\n  (\n    select 'client'::text, c.id, c.name,\n           concat_ws(' · ', nullif(c.document, ''), c.email, c.phone),\n           null::timestamptz,\n           (ts_rank(c.search, query.tsq) + similarity(c.name, q))::real\n    from public.clients c, query\n    where c.organization_id = org and c.archived_at is null\n      and (c.search @@ query.tsq or public.normalize_text(c.name) like query.pattern\n           or (length(query.digits) >= 4 and c.document like '%' || query.digits || '%'))\n    order by 6 desc limit max_results\n  )\n  union all\n  (\n    select 'process', p.id, p.number,\n           concat_ws(' · ', p.procedural_class, p.tribunal, p.court_division),\n           coalesce(p.next_hearing_at, p.next_deadline_at),\n           (ts_rank(p.search, query.tsq) + case when length(query.digits) >= 4 and regexp_replace(p.number, '\\D', '', 'g') like '%' || query.digits || '%' then 1 else 0 end)::real\n    from public.processes p, query\n    where p.organization_id = org\n      and (p.search @@ query.tsq\n           or (length(query.digits) >= 4 and regexp_replace(p.number, '\\D', '', 'g') like '%' || query.digits || '%')\n           or public.normalize_text(p.opposing_party) like query.pattern)\n    order by 6 desc limit max_results\n  )\n  union all\n  (\n    select 'event', e.id, e.title,\n           concat_ws(' · ', e.location, e.tribunal),\n           e.starts_at,\n           ts_rank(e.search, query.tsq)::real\n    from public.events e, query\n    where e.organization_id = org and e.deleted_at is null\n      and (e.search @@ query.tsq or public.normalize_text(e.title) like query.pattern)\n    order by 6 desc, e.starts_at desc limit max_results\n  )\n  union all\n  (\n    select 'note', e.id, e.title,\n           left(e.description_text, 140),\n           e.starts_at,\n           ts_rank(to_tsvector('portuguese', coalesce(e.description_text, '')), query.tsq)::real\n    from public.events e, query\n    where e.organization_id = org and e.deleted_at is null and e.description_text is not null\n      and to_tsvector('portuguese', e.description_text) @@ query.tsq\n    order by 6 desc limit greatest(3, max_results / 2)\n  )\n$$;\n\n-- ───────────────────────── Indicadores do painel ─────────────────────────\ncreate or replace function public.dashboard_metrics(org uuid, tz text default 'America/Sao_Paulo')\nreturns jsonb language sql stable security invoker set search_path = '' as $$\n  with bounds as (\n    select date_trunc('day', now() at time zone tz) at time zone tz as day_start,\n           (date_trunc('day', now() at time zone tz) + interval '1 day') at time zone tz as day_end,\n           date_trunc('month', now() at time zone tz) at time zone tz as month_start\n  ),\n  ev as (\n    select e.* from public.events e where e.organization_id = org and e.deleted_at is null\n  )\n  select jsonb_build_object(\n    'hearingsToday', (select count(*) from ev, bounds where kind = 'hearing' and starts_at >= day_start and starts_at < day_end and status <> 'cancelled'),\n    'deadlinesNext7', (select count(*) from ev where kind = 'deadline' and starts_at between now() and now() + interval '7 days' and status not in ('done','cancelled')),\n    'upcoming', (select count(*) from ev where starts_at > now() and status = 'scheduled'),\n    'pending', (select count(*) from ev where status in ('scheduled','in_progress') and starts_at <= now() + interval '7 days'),\n    'overdue', (select count(*) from ev where ends_at < now() and status in ('scheduled','in_progress') and kind in ('deadline','diligence','reminder','custom')),\n    'critical', (select count(*) from ev where priority = 'critical' and status not in ('done','cancelled') and starts_at >= now() - interval '1 day'),\n    'completedThisMonth', (select count(*) from ev, bounds where status = 'done' and updated_at >= month_start),\n    'createdThisMonth', (select count(*) from ev, bounds where created_at >= month_start),\n    'deadlinesMetOnTime', (select count(*) from ev, bounds where kind = 'deadline' and status = 'done' and updated_at <= ends_at and starts_at >= month_start),\n    'deadlinesTotalMonth', (select count(*) from ev, bounds where kind = 'deadline' and starts_at >= month_start and starts_at < now()),\n    'activeProcesses', (select count(*) from public.processes where organization_id = org and status = 'active'),\n    'clients', (select count(*) from public.clients where organization_id = org and archived_at is null),\n    'pendingSuggestions', (select count(*) from public.ai_suggestions where organization_id = org and status = 'pending'),\n    'checklistProgress', (\n      select coalesce(round(100.0 * count(*) filter (where i.is_done) / nullif(count(*), 0)), 0)\n      from public.event_checklist_items i join ev on ev.id = i.event_id\n      where ev.starts_at >= now() - interval '30 days'\n    ),\n    'weekly', (\n      select coalesce(jsonb_agg(jsonb_build_object('week', w.week, 'done', w.done, 'total', w.total) order by w.week), '[]'::jsonb)\n      from (\n        select date_trunc('week', starts_at at time zone tz)::date as week,\n               count(*) filter (where status = 'done') as done,\n               count(*) as total\n        from ev where starts_at >= now() - interval '8 weeks' and starts_at < now()\n        group by 1\n      ) w\n    )\n  )\n$$;\n\n-- ─────────────────── Aceitar sugestão da IA (cria evento) ───────────────────\ncreate or replace function public.accept_ai_suggestion(suggestion_id uuid)\nreturns uuid language plpgsql security invoker set search_path = '' as $$\ndeclare\n  s public.ai_suggestions;\n  p public.processes;\n  new_event uuid;\n  cat uuid;\nbegin\n  select * into s from public.ai_suggestions where id = suggestion_id and status = 'pending' for update;\n  if s.id is null then\n    raise exception 'Sugestão não encontrada ou já decidida';\n  end if;\n  select * into p from public.processes where id = s.process_id;\n  select id into cat from public.event_categories\n   where organization_id = s.organization_id and kind = s.kind::text::public.event_kind\n   order by position limit 1;\n\n  insert into public.events (\n    organization_id, title, kind, category_id, starts_at, ends_at, all_day,\n    process_id, client_id, tribunal, court_division, responsible_id, priority, source, created_by, description_text\n  ) values (\n    s.organization_id, s.title, s.kind::text::public.event_kind, cat,\n    coalesce(s.starts_at, now() + interval '1 day'),\n    coalesce(s.ends_at, coalesce(s.starts_at, now() + interval '1 day') + case when s.kind = 'hearing' then interval '1 hour' else interval '0' end),\n    s.kind = 'deadline',\n    p.id, p.client_id, p.tribunal, p.court_division, coalesce(p.responsible_id, auth.uid()),\n    case when s.kind in ('hearing', 'deadline') then 'high'::public.event_priority else 'medium'::public.event_priority end,\n    'ai', auth.uid(), s.rationale\n  ) returning id into new_event;\n\n  insert into public.event_reminders (event_id, user_id, offset_minutes)\n  select new_event, coalesce(p.responsible_id, auth.uid()), unnest(\n    case when s.kind = 'deadline' then array[1440, 4320, 10080] else array[60, 1440] end\n  )\n  on conflict do nothing;\n\n  update public.ai_suggestions\n     set status = 'accepted', event_id = new_event, decided_by = auth.uid(), decided_at = now()\n   where id = s.id;\n  return new_event;\nend $$;\n\n-- ─────────────────────────── Realtime ───────────────────────────\nalter publication supabase_realtime add table public.events;\nalter publication supabase_realtime add table public.notifications;\nalter publication supabase_realtime add table public.ai_suggestions;\nalter publication supabase_realtime add table public.event_comments;\nalter publication supabase_realtime add table public.event_checklist_items;\n" },
  { name: "20261007000004_intimations.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Monitoramento de intimações\n--   • pela OAB, no Diário de Justiça Eletrônico Nacional (DJEN/CNJ — Res. 455/2022)\n--   • pelos avisos pendentes do PJe (MNI), com CPF e senha do advogado\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate table public.oab_monitors (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  user_id uuid not null references auth.users (id) on delete cascade,\n  oab_number text not null check (oab_number ~ '^[0-9]{1,7}[A-Za-z]?$'),\n  oab_state char(2) not null,\n  is_active boolean not null default true,\n  last_checked_at timestamptz,\n  last_error text,\n  created_at timestamptz not null default now(),\n  unique (organization_id, oab_number, oab_state)\n);\ncreate index oab_monitors_active_idx on public.oab_monitors (is_active, last_checked_at);\n\ncreate table public.intimations (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  process_id uuid references public.processes (id) on delete set null,\n  monitor_id uuid references public.oab_monitors (id) on delete set null,\n  user_id uuid references auth.users (id) on delete set null,   -- advogado destinatário\n  source text not null default 'djen' check (source in ('djen', 'pje')),\n  external_id text not null,\n  process_number text not null,\n  tribunal text,\n  organ text,                         -- órgão julgador / vara\n  class_name text,\n  communication_type text,            -- Intimação, Citação, Edital...\n  document_type text,                 -- Decisão, Despacho, Sentença...\n  available_at date,                  -- disponibilização no diário\n  published_at date,                  -- publicação: 1º dia útil seguinte (Lei 11.419/2006, art. 4º, §3º)\n  tacit_awareness_at date,            -- PJe: ciência tácita (art. 5º, §3º)\n  text text,\n  link text,\n  parties jsonb not null default '[]'::jsonb,\n  lawyers jsonb not null default '[]'::jsonb,\n  read_at timestamptz,\n  created_at timestamptz not null default now(),\n  unique (organization_id, source, external_id)\n);\ncreate index intimations_org_idx on public.intimations (organization_id, available_at desc);\ncreate index intimations_unread_idx on public.intimations (organization_id, read_at) where read_at is null;\ncreate index intimations_process_idx on public.intimations (process_id);\n\nalter table public.court_credentials\n  add column last_checked_at timestamptz,\n  add column last_error text;\ngrant select (last_checked_at, last_error) on public.court_credentials to authenticated;\n\n-- ─────────────────────────────── RLS ───────────────────────────────\nalter table public.oab_monitors enable row level security;\nalter table public.intimations enable row level security;\n\ncreate policy \"monitores de OAB: membros leem\" on public.oab_monitors\n  for select using (public.is_member(organization_id));\ncreate policy \"monitores de OAB: advogado cadastra a própria\" on public.oab_monitors\n  for insert with check (public.is_member(organization_id) and user_id = auth.uid());\ncreate policy \"monitores de OAB: dono ou admin altera\" on public.oab_monitors\n  for update using (user_id = auth.uid() or public.has_role(organization_id, '{admin,partner}'));\ncreate policy \"monitores de OAB: dono ou admin remove\" on public.oab_monitors\n  for delete using (user_id = auth.uid() or public.has_role(organization_id, '{admin,partner}'));\n\ncreate policy \"intimações: membros leem\" on public.intimations\n  for select using (public.is_member(organization_id));\ncreate policy \"intimações: membros marcam como lidas\" on public.intimations\n  for update using (public.is_member(organization_id));\n\nalter publication supabase_realtime add table public.intimations;\n" },
  { name: "20261007000005_event_kind_task.sql", sql: "-- Lex Calendário — novo tipo de compromisso: Tarefa\n-- (em migration própria: um valor novo de enum não pode ser usado na mesma transação em que é criado)\nalter type public.event_kind add value if not exists 'task' after 'deadline';\n" },
  { name: "20261007000006_attendees_metrics.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Convidados nos compromissos e indicadores do painel\n-- ════════════════════════════════════════════════════════════════════════════\n\n-- Convidados: [{ \"email\": \"...\", \"name\": \"...\", \"status\": \"needsAction|accepted|declined|tentative\" }]\nalter table public.events add column attendees jsonb not null default '[]'::jsonb;\n\n-- Indicadores: eventos importados de outras agendas (Google, Outlook, iCloud, ICS) não têm\n-- controle de conclusão no Lex — não entram em \"pendentes\" nem em \"atrasados\".\ncreate or replace function public.dashboard_metrics(org uuid, tz text default 'America/Sao_Paulo')\nreturns jsonb language sql stable security invoker set search_path = '' as $$\n  with bounds as (\n    select date_trunc('day', now() at time zone tz) at time zone tz as day_start,\n           (date_trunc('day', now() at time zone tz) + interval '1 day') at time zone tz as day_end,\n           date_trunc('month', now() at time zone tz) at time zone tz as month_start\n  ),\n  ev as (\n    select e.* from public.events e where e.organization_id = org and e.deleted_at is null\n  ),\n  own as (\n    select * from ev where source in ('lex', 'ai')\n  )\n  select jsonb_build_object(\n    'hearingsToday', (select count(*) from ev, bounds where kind = 'hearing' and starts_at >= day_start and starts_at < day_end and status <> 'cancelled'),\n    'deadlinesNext7', (select count(*) from ev where kind = 'deadline' and ends_at >= now() and starts_at <= now() + interval '7 days' and status not in ('done','cancelled')),\n    'upcoming', (select count(*) from ev where starts_at > now() and status in ('scheduled','in_progress')),\n    'pending', (select count(*) from own where status in ('scheduled','in_progress') and starts_at <= now() + interval '7 days' and ends_at >= now()),\n    'overdue', (select count(*) from own where ends_at < now() and status in ('scheduled','in_progress') and kind in ('deadline','task','diligence','reminder')),\n    'critical', (select count(*) from ev where priority = 'critical' and status not in ('done','cancelled') and ends_at >= now()),\n    'completedThisMonth', (select count(*) from ev, bounds where status = 'done' and updated_at >= month_start),\n    'createdThisMonth', (select count(*) from own, bounds where created_at >= month_start),\n    'deadlinesMetOnTime', (select count(*) from ev, bounds where kind = 'deadline' and status = 'done' and updated_at <= ends_at and starts_at >= month_start),\n    'deadlinesTotalMonth', (select count(*) from ev, bounds where kind = 'deadline' and starts_at >= month_start and starts_at < now()),\n    'activeProcesses', (select count(*) from public.processes where organization_id = org and status = 'active'),\n    'clients', (select count(*) from public.clients where organization_id = org and archived_at is null),\n    'pendingSuggestions', (select count(*) from public.ai_suggestions where organization_id = org and status = 'pending'),\n    'unreadIntimations', (select count(*) from public.intimations where organization_id = org and read_at is null),\n    'checklistProgress', (\n      select coalesce(round(100.0 * count(*) filter (where i.is_done) / nullif(count(*), 0)), 0)\n      from public.event_checklist_items i join ev on ev.id = i.event_id\n      where ev.starts_at >= now() - interval '30 days'\n    ),\n    'weekly', (\n      select coalesce(jsonb_agg(jsonb_build_object('week', w.week, 'done', w.done, 'total', w.total) order by w.week), '[]'::jsonb)\n      from (\n        select date_trunc('week', starts_at at time zone tz)::date as week,\n               count(*) filter (where status = 'done') as done,\n               count(*) as total\n        from own where starts_at >= now() - interval '8 weeks' and starts_at < now()\n        group by 1\n      ) w\n    )\n  )\n$$;\n\n-- ───────────── Categoria \"Tarefa\" (escritórios existentes e novos) ─────────────\ninsert into public.event_categories (organization_id, kind, name, color, position)\nselect o.id, 'task', 'Tarefa', '#5856D6', 8 from public.organizations o\non conflict (organization_id, name) do nothing;\n\ncreate or replace function public.seed_default_categories(org uuid)\nreturns void language sql security definer set search_path = '' as $$\n  insert into public.event_categories (organization_id, kind, name, color, position) values\n    (org, 'hearing',      'Audiência',           '#D93F3F', 0),\n    (org, 'deadline',     'Prazo',               '#E8833A', 1),\n    (org, 'task',         'Tarefa',              '#5856D6', 2),\n    (org, 'meeting',      'Reunião',             '#3478F6', 3),\n    (org, 'diligence',    'Diligência',          '#8E5BD9', 4),\n    (org, 'consultation', 'Consulta',            '#2BA59A', 5),\n    (org, 'service',      'Atendimento',         '#556B2F', 6),\n    (org, 'reminder',     'Lembrete',            '#E5B800', 7),\n    (org, 'custom',       'Evento personalizado','#8E8E93', 8)\n  on conflict (organization_id, name) do nothing\n$$;\n" },
  { name: "20261008000007_system_notifications.sql", sql: "-- Lex Calendário — notificações do sistema operacional (aplicativo desktop)\n-- Toda notificação da plataforma (lembretes, intimações, testes) também é mostrada\n-- como notificação nativa do sistema; esta coluna marca as já entregues.\nalter table public.notifications add column system_sent_at timestamptz;\ncreate index notifications_system_pending_idx on public.notifications (created_at) where system_sent_at is null;\n-- As notificações antigas não devem disparar de uma vez após a atualização\nupdate public.notifications set system_sent_at = now() where system_sent_at is null;\n" },
  { name: "20261008000008_communications.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Comunicações com clientes (e-mails, ofícios, WhatsApp)\n-- Modelos com variáveis, agendamento de envio, prazo e anexos; conta de e-mail (SMTP).\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate type public.communication_kind as enum ('email', 'oficio', 'whatsapp');\ncreate type public.communication_status as enum ('draft', 'scheduled', 'sent', 'failed', 'cancelled');\n\ncreate table public.communication_templates (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  name text not null,\n  kind public.communication_kind not null default 'email',\n  subject text not null default '',\n  body text not null default '',\n  is_default boolean not null default false,\n  created_by uuid references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (organization_id, name)\n);\n\ncreate table public.communications (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  kind public.communication_kind not null default 'email',\n  status public.communication_status not null default 'draft',\n  client_id uuid references public.clients (id) on delete set null,\n  process_id uuid references public.processes (id) on delete set null,\n  event_id uuid references public.events (id) on delete set null,        -- tarefa de prazo criada no calendário\n  template_id uuid references public.communication_templates (id) on delete set null,\n  to_email text,\n  to_phone text,\n  recipient_name text,\n  subject text not null default '',\n  body text not null default '',\n  deadline_at date,                     -- prazo informado ao destinatário\n  send_at timestamptz,                  -- envio agendado\n  sent_at timestamptz,\n  notified_at timestamptz,              -- WhatsApp/ofício agendados: aviso \"hora de enviar\" já dado\n  error text,\n  attachments jsonb not null default '[]'::jsonb,  -- [{ name, path, size, mime }]\n  generated_by_ai boolean not null default false,\n  created_by uuid references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index communications_org_idx on public.communications (organization_id, created_at desc);\ncreate index communications_client_idx on public.communications (client_id, created_at desc);\ncreate index communications_due_idx on public.communications (send_at) where status = 'scheduled';\n\n-- Conta de e-mail para envio (SMTP). A senha fica criptografada e nunca é lida pelo navegador.\ncreate table public.mail_accounts (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  user_id uuid not null references auth.users (id) on delete cascade,\n  host text not null,\n  port integer not null default 465,\n  secure boolean not null default true,\n  username text not null,\n  password_enc text,\n  from_name text,\n  from_email text not null,\n  last_test_at timestamptz,\n  last_error text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (organization_id, user_id)\n);\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['communication_templates','communications','mail_accounts']\n  loop\n    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', t);\n  end loop;\nend $$;\n\ncreate trigger log_activity after insert or update or delete on public.communications\n  for each row execute function public.log_activity();\n\n-- ─────────────────────────────── RLS ───────────────────────────────\nalter table public.communication_templates enable row level security;\nalter table public.communications enable row level security;\nalter table public.mail_accounts enable row level security;\n\ncreate policy \"modelos: membros leem\" on public.communication_templates for select using (public.is_member(organization_id));\ncreate policy \"modelos: membros gerenciam\" on public.communication_templates for all\n  using (public.has_role(organization_id, '{admin,partner,lawyer,assistant,secretary}'))\n  with check (public.has_role(organization_id, '{admin,partner,lawyer,assistant,secretary}'));\n\ncreate policy \"comunicações: membros leem\" on public.communications for select using (public.is_member(organization_id));\ncreate policy \"comunicações: membros criam\" on public.communications for insert with check (public.is_member(organization_id));\ncreate policy \"comunicações: membros editam\" on public.communications for update using (public.is_member(organization_id));\ncreate policy \"comunicações: autor ou admin remove\" on public.communications for delete\n  using (created_by = auth.uid() or public.has_role(organization_id, '{admin,partner}'));\n\ncreate policy \"conta de e-mail: dono\" on public.mail_accounts for select using (user_id = auth.uid());\ncreate policy \"conta de e-mail: dono remove\" on public.mail_accounts for delete using (user_id = auth.uid());\nrevoke select, insert, update on public.mail_accounts from authenticated, anon;\ngrant select (id, organization_id, user_id, host, port, secure, username, from_name, from_email, last_test_at, last_error, created_at, updated_at)\n  on public.mail_accounts to authenticated;\n\n-- ─────────────────────────── Modelos padrão ───────────────────────────\ncreate or replace function public.seed_communication_templates(org uuid)\nreturns void language sql security definer set search_path = '' as $$\n  insert into public.communication_templates (organization_id, name, kind, subject, body, is_default) values\n  (org, 'Comunicado de audiência', 'email', 'Audiência designada — processo {{processo}}',\n'Prezado(a) {{cliente}},\n\nInformamos que foi designada audiência no processo nº {{processo}}, em trâmite perante {{vara}} ({{tribunal}}).\n\nData e horário: {{data_evento}}\nLocal: {{local_evento}}\n\nPedimos que confirme sua presença até {{prazo}} e que compareça com 30 minutos de antecedência, portando documento de identificação com foto.\n\nPermanecemos à disposição para quaisquer esclarecimentos.\n\nAtenciosamente,\n{{advogado}} — OAB {{oab}}\n{{escritorio}}', true),\n  (org, 'Solicitação de documentos', 'email', 'Documentos necessários — {{processo}}',\n'Prezado(a) {{cliente}},\n\nPara darmos andamento ao seu processo nº {{processo}}, solicitamos o envio dos seguintes documentos até {{prazo}}:\n\n1.\n2.\n3.\n\nOs documentos podem ser enviados em resposta a este e-mail (PDF ou foto legível).\n\nAtenciosamente,\n{{advogado}} — OAB {{oab}}\n{{escritorio}}', true),\n  (org, 'Informe de andamento processual', 'email', 'Andamento do processo {{processo}}',\n'Prezado(a) {{cliente}},\n\nComunicamos a última movimentação do processo nº {{processo}} ({{tribunal}} — {{vara}}):\n\n{{ultima_movimentacao}}\n\nPróximos passos:\n\nQualquer dúvida, estamos à disposição.\n\nAtenciosamente,\n{{advogado}} — OAB {{oab}}\n{{escritorio}}', true),\n  (org, 'Lembrete de reunião', 'whatsapp', 'Lembrete de reunião',\n'Olá, {{cliente}}! Lembramos da nossa reunião em {{data_evento}} ({{local_evento}}). Por favor, confirme sua presença. — {{escritorio}}', true),\n  (org, 'Ofício', 'oficio', 'Ofício nº ___/{{ano}}',\n'OFÍCIO Nº ___/{{ano}}\n\nBelém (PA), {{hoje}}.\n\nA(o) Ilustríssimo(a) Senhor(a)\n[Destinatário]\n[Cargo / Órgão]\n[Endereço]\n\nAssunto: [assunto]\nReferência: processo nº {{processo}} — {{vara}} ({{tribunal}})\n\nSenhor(a),\n\nNa qualidade de advogado(a) de {{cliente}}, venho, respeitosamente, solicitar [descrever a solicitação], no prazo de {{prazo}}, nos termos da legislação aplicável.\n\nSem mais para o momento, renovo protestos de elevada estima e consideração.\n\nAtenciosamente,\n\n{{advogado}}\nOAB {{oab}}\n{{escritorio}}', true)\n  on conflict (organization_id, name) do nothing\n$$;\n\nselect public.seed_communication_templates(id) from public.organizations;\n\n-- Novos escritórios recebem os modelos padrão\ncreate or replace function public.on_organization_created_seed_templates()\nreturns trigger language plpgsql security definer set search_path = '' as $$\nbegin\n  perform public.seed_communication_templates(new.id);\n  return new;\nend $$;\n\ncreate trigger seed_communication_templates after insert on public.organizations\n  for each row execute function public.on_organization_created_seed_templates();\n" },
  { name: "20261008000009_collaborators.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Responsáveis sem conta no app (estagiários, colegas, secretárias,\n-- correspondentes, convidados por e-mail) que podem receber tarefas.\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate table public.collaborators (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  name text not null check (char_length(name) between 2 and 200),\n  email text,\n  phone text,\n  role text,                       -- função: advogado(a), estagiário(a), secretária, correspondente...\n  oab text,\n  is_active boolean not null default true,\n  created_by uuid references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index collaborators_org_idx on public.collaborators (organization_id, name);\ncreate unique index collaborators_org_email_idx on public.collaborators (organization_id, lower(email)) where email is not null;\n\ncreate trigger set_updated_at before update on public.collaborators for each row execute function public.set_updated_at();\n\nalter table public.events add column collaborator_id uuid references public.collaborators (id) on delete set null;\ncreate index events_collaborator_idx on public.events (collaborator_id) where collaborator_id is not null;\n\nalter table public.collaborators enable row level security;\ncreate policy \"responsáveis: membros leem\" on public.collaborators for select using (public.is_member(organization_id));\ncreate policy \"responsáveis: equipe gerencia\" on public.collaborators for all\n  using (public.has_role(organization_id, '{admin,partner,lawyer,assistant,secretary}'))\n  with check (public.has_role(organization_id, '{admin,partner,lawyer,assistant,secretary}'));\n\n-- ─────────────── Tarefa relacionada e data de conclusão ───────────────\n-- Uma nova tarefa pode apontar para outra já concluída; a descrição enviada ao Google\n-- informa o que foi executado e quando.\nalter table public.events\n  add column related_event_id uuid references public.events (id) on delete set null,\n  add column completed_at timestamptz;\ncreate index events_related_idx on public.events (related_event_id) where related_event_id is not null;\n\nupdate public.events set completed_at = updated_at where status = 'done' and completed_at is null;\n\ncreate or replace function public.set_event_completed_at()\nreturns trigger language plpgsql as $$\nbegin\n  if new.status = 'done' and (tg_op = 'INSERT' or old.status is distinct from 'done') then\n    new.completed_at := coalesce(new.completed_at, now());\n  elsif new.status <> 'done' then\n    new.completed_at := null;\n  end if;\n  return new;\nend $$;\n\ncreate trigger set_event_completed_at before insert or update of status on public.events\n  for each row execute function public.set_event_completed_at();\n" },
  { name: "20261008000010_sync_reconcile.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Sincronização confiável com Google Agenda\n-- Alterações feitas no Lex que não chegaram ao Google (janela fechada, servidor\n-- reiniciando, falha da API) são reenviadas pela sincronização periódica.\n-- ════════════════════════════════════════════════════════════════════════════\n\n-- Erros de envio ficam separados dos de leitura (a leitura bem-sucedida não os apaga)\nalter table public.calendar_connections\n  add column last_push_error text,\n  add column last_push_error_at timestamptz;\ngrant select (last_push_error, last_push_error_at) on public.calendar_connections to authenticated;\n\n-- Checklist, comentários e anexos fazem parte da descrição no Google: alterá-los marca o compromisso como alterado\ncreate or replace function public.touch_parent_event()\nreturns trigger language plpgsql security definer set search_path = '' as $$\ndeclare\n  eid uuid := coalesce(case when tg_op = 'DELETE' then old.event_id else new.event_id end, null);\nbegin\n  if eid is not null then\n    update public.events set updated_at = now() where id = eid and updated_at < now();\n  end if;\n  return null;\nend $$;\n\ndo $$\ndeclare t text;\nbegin\n  foreach t in array array['event_checklist_items', 'event_comments', 'event_attachments']\n  loop\n    execute format('drop trigger if exists touch_parent_event on public.%I', t);\n    execute format('create trigger touch_parent_event after insert or update or delete on public.%I for each row execute function public.touch_parent_event()', t);\n  end loop;\nend $$;\n\n-- Compromissos com alterações ainda não enviadas a uma conexão.\n-- Eventos vindos do Google só são reenviados quando um usuário os alterou no Lex\n-- (evita reescrever a agenda inteira depois de uma importação de backup).\ncreate or replace function public.sync_pending_events(conn uuid, max_rows integer default 25)\nreturns table (event_id uuid)\nlanguage sql stable security definer set search_path = '' as $$\n  select e.id\n  from public.calendar_connections c\n  join public.events e on e.organization_id = c.organization_id\n  left join public.event_external_links l on l.event_id = e.id and l.connection_id = c.id\n  where c.id = conn\n    and c.is_active\n    and (e.responsible_id = c.user_id or e.created_by = c.user_id)\n    and e.ends_at > now() - interval '90 days'\n    and (\n      (l.event_id is null and e.deleted_at is null and e.source in ('lex', 'ai'))\n      or (l.event_id is not null and e.deleted_at is not null)\n      or (\n        l.event_id is not null and e.deleted_at is null\n        and e.updated_at > l.last_synced_at + interval '2 seconds'\n        and (\n          e.source in ('lex', 'ai')\n          or exists (\n            select 1 from public.activity_log a\n            where (a.entity_id = e.id or a.parent_id = e.id)\n              and a.actor_id is not null\n              and a.created_at > l.last_synced_at\n          )\n        )\n      )\n    )\n  order by e.updated_at desc\n  limit max_rows\n$$;\nrevoke execute on function public.sync_pending_events(uuid, integer) from public, anon, authenticated;\n\ncreate or replace view public.calendar_connections_public with (security_invoker = true) as\n  select id, organization_id, user_id, provider, account_email, external_calendar_id,\n         last_synced_at, last_error, is_active, created_at, last_push_error, last_push_error_at\n  from public.calendar_connections;\n" },
  { name: "20261008000011_process_title.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Nome do processo e número opcional\n-- O advogado identifica o processo por um nome (\"Cobrança — contra Banco X\") e pelo\n-- número CNJ quando houver (processos ainda não ajuizados ficam sem número).\n-- ════════════════════════════════════════════════════════════════════════════\n\nalter table public.processes add column title text;\nalter table public.processes alter column number drop not null;\n\n-- Busca textual inclui o nome\ndrop index if exists public.processes_search_idx;\nalter table public.processes drop column search;\nalter table public.processes add column search tsvector generated always as (\n  setweight(to_tsvector('portuguese', coalesce(title, '')), 'A') ||\n  setweight(to_tsvector('simple', coalesce(number, '')), 'A') ||\n  setweight(to_tsvector('simple', regexp_replace(coalesce(number, ''), '\\D', '', 'g')), 'A') ||\n  setweight(to_tsvector('portuguese', coalesce(procedural_class, '')), 'B') ||\n  setweight(to_tsvector('portuguese', coalesce(subject, '')), 'B') ||\n  setweight(to_tsvector('portuguese', coalesce(opposing_party, '')), 'B') ||\n  setweight(to_tsvector('simple', coalesce(tribunal, '')), 'C') ||\n  setweight(to_tsvector('portuguese', coalesce(court_division, '')), 'C') ||\n  setweight(to_tsvector('portuguese', coalesce(notes, '')), 'D')\n) stored;\ncreate index processes_search_idx on public.processes using gin (search);\n\n-- Processo precisa de nome ou número\nalter table public.processes add constraint processes_title_or_number\n  check (coalesce(nullif(btrim(title), ''), nullif(btrim(number), '')) is not null);\n\ncreate or replace function public.global_search(org uuid, q text, max_results int default 8)\nreturns table (\n  entity_type text,\n  id uuid,\n  title text,\n  subtitle text,\n  starts_at timestamptz,\n  rank real\n) language sql stable security invoker set search_path = public, extensions as $$\n  with query as (\n    select websearch_to_tsquery('portuguese', q) as tsq,\n           '%' || public.normalize_text(q) || '%' as pattern,\n           regexp_replace(q, '\\D', '', 'g') as digits\n  )\n  (\n    select 'client'::text, c.id, c.name,\n           concat_ws(' · ', nullif(c.document, ''), c.email, c.phone),\n           null::timestamptz,\n           (ts_rank(c.search, query.tsq) + similarity(c.name, q))::real\n    from public.clients c, query\n    where c.organization_id = org and c.archived_at is null\n      and (c.search @@ query.tsq or public.normalize_text(c.name) like query.pattern\n           or (length(query.digits) >= 4 and c.document like '%' || query.digits || '%'))\n    order by 6 desc limit max_results\n  )\n  union all\n  (\n    select 'process', p.id, coalesce(nullif(concat_ws(' — ', p.title, p.number), ''), 'Processo'),\n           concat_ws(' · ', p.procedural_class, p.tribunal, p.court_division),\n           coalesce(p.next_hearing_at, p.next_deadline_at),\n           (ts_rank(p.search, query.tsq) + case when length(query.digits) >= 4 and regexp_replace(p.number, '\\D', '', 'g') like '%' || query.digits || '%' then 1 else 0 end)::real\n    from public.processes p, query\n    where p.organization_id = org\n      and (p.search @@ query.tsq\n           or (length(query.digits) >= 4 and regexp_replace(p.number, '\\D', '', 'g') like '%' || query.digits || '%')\n           or public.normalize_text(p.opposing_party) like query.pattern\n           or public.normalize_text(p.title) like query.pattern)\n    order by 6 desc limit max_results\n  )\n  union all\n  (\n    select 'event', e.id, e.title,\n           concat_ws(' · ', e.location, e.tribunal),\n           e.starts_at,\n           ts_rank(e.search, query.tsq)::real\n    from public.events e, query\n    where e.organization_id = org and e.deleted_at is null\n      and (e.search @@ query.tsq or public.normalize_text(e.title) like query.pattern)\n    order by 6 desc, e.starts_at desc limit max_results\n  )\n  union all\n  (\n    select 'note', e.id, e.title,\n           left(e.description_text, 140),\n           e.starts_at,\n           ts_rank(to_tsvector('portuguese', coalesce(e.description_text, '')), query.tsq)::real\n    from public.events e, query\n    where e.organization_id = org and e.deleted_at is null and e.description_text is not null\n      and to_tsvector('portuguese', e.description_text) @@ query.tsq\n    order by 6 desc limit greatest(3, max_results / 2)\n  )\n$$;\n" },
  { name: "20261008000012_hearing_title_prefix.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Audiências salvas com \"AUDIÊNCIA:\" no início do nome\n-- Vale para compromissos criados no Lex (manual, IA, intimações). Ao mudar o tipo\n-- para outro, o prefixo é retirado. Eventos vindos do Google mantêm o nome original.\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate or replace function public.apply_hearing_prefix()\nreturns trigger language plpgsql as $$\ndeclare\n  prefix_re constant text := '^\\s*audi[eê]ncia\\s*:\\s*';\nbegin\n  if new.source not in ('lex', 'ai') then\n    return new;\n  end if;\n  if new.kind = 'hearing' then\n    if new.title !~* prefix_re then\n      new.title := 'AUDIÊNCIA: ' || btrim(new.title);\n    else\n      new.title := regexp_replace(new.title, prefix_re, 'AUDIÊNCIA: ', 'i');\n    end if;\n  elsif tg_op = 'UPDATE' and old.kind = 'hearing' and new.title ~* prefix_re then\n    new.title := regexp_replace(new.title, prefix_re, '', 'i');\n  end if;\n  return new;\nend $$;\n\ncreate trigger apply_hearing_prefix before insert or update of title, kind on public.events\n  for each row execute function public.apply_hearing_prefix();\n\n-- Audiências já cadastradas no Lex\nupdate public.events\n   set title = 'AUDIÊNCIA: ' || btrim(title)\n where kind = 'hearing' and source in ('lex', 'ai') and deleted_at is null and title !~* '^\\s*audi[eê]ncia\\s*:';\n" },
  { name: "20261008000013_merge_duplicate_events.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — União de compromissos duplicados\n-- Restaurar um backup numa instalação nova trazia os compromissos sem o vínculo com o\n-- Google; a sincronização seguinte importava tudo de novo. Esta rotina une as cópias\n-- (mesmo nome, início e fim), mantendo a que tem mais informação do Lex e o vínculo\n-- com o Google, e leva para ela checklist, comentários e anexos das outras.\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate or replace function public.merge_duplicate_events(org uuid default null)\nreturns integer language plpgsql security definer set search_path = '' as $$\ndeclare\n  g record;\n  keeper uuid;\n  loser uuid;\n  merged integer := 0;\nbegin\n  for g in\n    select array_agg(e.id order by (\n             (e.client_id is not null)::int * 4\n           + (e.process_id is not null)::int * 4\n           + (select count(*) from public.event_checklist_items c where c.event_id = e.id)::int\n           + 2 * (select count(*) from public.event_comments c where c.event_id = e.id)::int\n           + 2 * (select count(*) from public.event_attachments c where c.event_id = e.id)::int\n           + 3 * (e.source in ('lex', 'ai'))::int\n           + 2 * (exists (select 1 from public.event_external_links l where l.event_id = e.id))::int\n         ) desc, e.created_at) as ids\n    from public.events e\n    where e.deleted_at is null\n      and (org is null or e.organization_id = org)\n    group by e.organization_id,\n             regexp_replace(lower(btrim(e.title)), '^\\s*(✔️|✔|✅)\\s*', ''),\n             e.starts_at, e.ends_at\n    having count(*) > 1\n  loop\n    keeper := g.ids[1];\n    foreach loser in array g.ids[2:array_length(g.ids, 1)]\n    loop\n      -- Cópia ligada a outro evento do Google na mesma conta: o Google também tem a cópia.\n      -- Só é apagada (no Lex e, pela sincronização, no Google) se tiver o mesmo nome, horário e local\n      -- e nenhum dado do Lex (cliente, processo, checklist, comentários, anexos).\n      if exists (\n        select 1 from public.event_external_links a\n        join public.event_external_links b on b.connection_id = a.connection_id\n        where a.event_id = loser and b.event_id = keeper\n      ) then\n        if exists (\n          select 1 from public.events l, public.events k\n          where l.id = loser and k.id = keeper\n            and l.client_id is null and l.process_id is null and l.collaborator_id is null\n            and l.location is not distinct from k.location\n            and not exists (select 1 from public.event_checklist_items c where c.event_id = loser)\n            and not exists (select 1 from public.event_comments c where c.event_id = loser)\n            and not exists (select 1 from public.event_attachments c where c.event_id = loser)\n        ) then\n          update public.events set deleted_at = now() where id = loser;\n          merged := merged + 1;\n        end if;\n        continue;\n      end if;\n      update public.event_external_links set event_id = keeper where event_id = loser;\n\n      update public.events k set\n        client_id = coalesce(k.client_id, l.client_id),\n        process_id = coalesce(k.process_id, l.process_id),\n        tribunal = coalesce(k.tribunal, l.tribunal),\n        court_division = coalesce(k.court_division, l.court_division),\n        description_text = coalesce(k.description_text, l.description_text),\n        description = coalesce(k.description, l.description),\n        collaborator_id = coalesce(k.collaborator_id, l.collaborator_id),\n        related_event_id = coalesce(k.related_event_id, nullif(l.related_event_id, k.id))\n      from public.events l\n      where k.id = keeper and l.id = loser;\n\n      if not exists (select 1 from public.event_checklist_items where event_id = keeper) then\n        update public.event_checklist_items set event_id = keeper where event_id = loser;\n      end if;\n      update public.event_comments set event_id = keeper where event_id = loser;\n      update public.event_attachments set event_id = keeper where event_id = loser;\n      update public.events set related_event_id = keeper where related_event_id = loser;\n      update public.communications set event_id = keeper where event_id = loser;\n\n      update public.events set deleted_at = now() where id = loser;\n      merged := merged + 1;\n    end loop;\n  end loop;\n  return merged;\nend $$;\nrevoke execute on function public.merge_duplicate_events(uuid) from public, anon, authenticated;\n\n-- Sugestões da IA repetidas (mesma publicação recebida por mais de uma intimação)\ncreate or replace function public.skip_duplicate_suggestion()\nreturns trigger language plpgsql security definer set search_path = '' as $$\nbegin\n  if exists (\n    select 1 from public.ai_suggestions s\n    where s.organization_id = new.organization_id\n      and s.process_id = new.process_id\n      and s.kind = new.kind\n      and s.title = new.title\n      and s.starts_at is not distinct from new.starts_at\n      and s.status <> 'dismissed'\n  ) then\n    return null; -- já existe: não cria outra\n  end if;\n  return new;\nend $$;\n\ncreate trigger skip_duplicate_suggestion before insert on public.ai_suggestions\n  for each row execute function public.skip_duplicate_suggestion();\n\ndelete from public.ai_suggestions s\nusing public.ai_suggestions o\nwhere s.status = 'pending'\n  and o.organization_id = s.organization_id and o.process_id = s.process_id and o.kind = s.kind\n  and o.title = s.title and o.starts_at is not distinct from s.starts_at\n  and o.status <> 'dismissed'\n  and (o.created_at, o.id) < (s.created_at, s.id);\n\nselect public.merge_duplicate_events(null);\n" },
  { name: "20261008000014_partners_hearing_mode.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Cadastro de parceiros e modalidade da audiência\n-- ════════════════════════════════════════════════════════════════════════════\n\n-- Parceiros: escritórios e advogados correspondentes, peritos, contadores,\n-- indicadores de clientes etc. Podem ser vinculados a processos, com a divisão de honorários.\ncreate table public.partners (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  kind text not null default 'individual' check (kind in ('individual', 'company')),\n  category text not null default 'correspondente',\n  name text not null check (char_length(name) between 2 and 200),\n  trade_name text,\n  document text,\n  oab text,\n  email text,\n  phone text,\n  secondary_phone text,\n  website text,\n  address_city text,\n  address_state text,\n  specialties text,                    -- áreas de atuação\n  fee_percent numeric(5, 2) check (fee_percent between 0 and 100),  -- divisão de honorários padrão\n  bank_info text,                      -- dados para repasse (PIX, banco)\n  notes text,\n  is_active boolean not null default true,\n  created_by uuid references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index partners_org_idx on public.partners (organization_id, name);\ncreate trigger set_updated_at before update on public.partners for each row execute function public.set_updated_at();\n\nalter table public.partners enable row level security;\ncreate policy \"parceiros: membros leem\" on public.partners for select using (public.is_member(organization_id));\ncreate policy \"parceiros: equipe gerencia\" on public.partners for all\n  using (public.has_role(organization_id, '{admin,partner,lawyer,assistant,secretary}'))\n  with check (public.has_role(organization_id, '{admin,partner,lawyer,assistant,secretary}'));\n\nalter table public.processes\n  add column partner_id uuid references public.partners (id) on delete set null,\n  add column partner_fee_percent numeric(5, 2) check (partner_fee_percent between 0 and 100);\ncreate index processes_partner_idx on public.processes (partner_id) where partner_id is not null;\n\n-- Audiência on-line ou presencial\nalter table public.events add column hearing_mode text check (hearing_mode in ('online', 'presencial'));\n" },
  { name: "20261008000015_partner_responsible.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Parceiro como responsável por tarefas e compromissos\n-- ════════════════════════════════════════════════════════════════════════════\nalter table public.events add column partner_id uuid references public.partners (id) on delete set null;\ncreate index events_partner_idx on public.events (partner_id) where partner_id is not null;\n" },
  { name: "20261008000016_gmail_send.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Envio de e-mails pelo Gmail (permissão gmail.send da conta Google)\n-- ════════════════════════════════════════════════════════════════════════════\nalter table public.calendar_connections add column scopes text;\ngrant select (scopes) on public.calendar_connections to authenticated;\n\ncreate or replace view public.calendar_connections_public with (security_invoker = true) as\n  select id, organization_id, user_id, provider, account_email, external_calendar_id,\n         last_synced_at, last_error, is_active, created_at, last_push_error, last_push_error_at, scopes\n  from public.calendar_connections;\n" },
  { name: "20261008000017_guest_updates.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Avisos aos convidados só em mudanças importantes; convidados\n-- podem alterar data/hora e comentar pelo Google Agenda\n-- ════════════════════════════════════════════════════════════════════════════\n\n-- Impressão digital do que importa ao convidado (data, hora, local, link, convidados) no último envio\nalter table public.event_external_links add column notify_hash text;\n\n-- Convidados podem alterar o evento no Google Agenda (padrão: sim)\nalter table public.events add column guests_can_modify boolean not null default true;\n\n-- Observações deixadas pelos convidados ao responder o convite, já importadas como comentário\nalter table public.event_comments add column external_ref text;\ncreate unique index event_comments_external_ref_idx on public.event_comments (event_id, external_ref) where external_ref is not null;\n" },
  { name: "20261008000018_process_notes.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Anotações nos processos (datadas, com autor)\n-- ════════════════════════════════════════════════════════════════════════════\ncreate table public.process_notes (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  process_id uuid not null references public.processes (id) on delete cascade,\n  author_id uuid references auth.users (id) on delete set null,\n  body text not null check (char_length(body) between 1 and 20000),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index process_notes_process_idx on public.process_notes (process_id, created_at);\ncreate trigger set_updated_at before update on public.process_notes for each row execute function public.set_updated_at();\n\nalter table public.process_notes enable row level security;\ncreate policy \"anotações: membros leem\" on public.process_notes for select using (public.is_member(organization_id));\ncreate policy \"anotações: membros escrevem\" on public.process_notes for insert with check (public.is_member(organization_id));\ncreate policy \"anotações: autor ou admin edita\" on public.process_notes for update\n  using (author_id = auth.uid() or public.has_role(organization_id, '{admin,partner}'));\ncreate policy \"anotações: autor ou admin remove\" on public.process_notes for delete\n  using (author_id = auth.uid() or public.has_role(organization_id, '{admin,partner}'));\n" },
  { name: "20261008000019_client_contacts.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Contatos do cliente para comunicação (pessoas terceiras)\n-- ════════════════════════════════════════════════════════════════════════════\ncreate table public.client_contacts (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  client_id uuid not null references public.clients (id) on delete cascade,\n  name text not null check (char_length(name) between 2 and 200),\n  relationship text,                 -- cônjuge, filho(a), secretária, contador, representante legal…\n  email text,\n  phone text,\n  notes text,\n  receives_communications boolean not null default true,\n  created_by uuid references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index client_contacts_client_idx on public.client_contacts (client_id, name);\ncreate trigger set_updated_at before update on public.client_contacts for each row execute function public.set_updated_at();\n\nalter table public.client_contacts enable row level security;\ncreate policy \"contatos: membros leem\" on public.client_contacts for select using (public.is_member(organization_id));\ncreate policy \"contatos: equipe gerencia\" on public.client_contacts for all\n  using (public.has_role(organization_id, '{admin,partner,lawyer,assistant,secretary}'))\n  with check (public.has_role(organization_id, '{admin,partner,lawyer,assistant,secretary}'));\n\n-- Comunicação enviada a um contato do cliente\nalter table public.communications add column contact_id uuid references public.client_contacts (id) on delete set null;\n" },
  { name: "20261008000020_co_responsibles.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Mais de um responsável por tarefa/compromisso\n-- Lista de responsáveis adicionais: [{ \"type\": \"member\"|\"collaborator\"|\"partner\", \"id\": \"<uuid>\" }]\n-- ════════════════════════════════════════════════════════════════════════════\nalter table public.events add column co_responsibles jsonb not null default '[]'::jsonb;\n\n-- ════════════════════════════════════════════════════════════════════════════\n-- Tipo de contrato do cliente: por trabalho (por causa/serviço) ou fixo (mensal)\n-- ════════════════════════════════════════════════════════════════════════════\nalter table public.clients\n  add column contract_type text check (contract_type in ('trabalho', 'fixo')),\n  add column contract_value numeric(14, 2),\n  add column contract_notes text;\n" },
  { name: "20261010000021_shared_events_profile.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Eventos compartilhados entre instalações do Lex (via Google Agenda),\n-- respostas de e-mail como comentários e função (profissão) no perfil\n-- ════════════════════════════════════════════════════════════════════════════\n\n-- Perfil: função/profissão da pessoa (advogado, engenheiro, médico…)\nalter table public.profiles\n  add column profession text,\n  add column document text;   -- CPF (para buscar intimações pelo nome/CPF de quem não é advogado)\n\n-- Comentários vindos de outra pessoa (convidado, outra instalação do Lex, resposta por e-mail)\nalter table public.event_comments\n  add column author_name text,\n  add column author_email text;\n\n-- Evento em que este usuário é CONVIDADO (o organizador é outra conta):\n--   shared_origin   e-mail do organizador\n--   shared_readonly o organizador não permite alterações (o convidado ainda pode comentar)\nalter table public.events\n  add column shared_origin text,\n  add column shared_readonly boolean not null default false;\n\n-- Conversas de e-mail dos comentários (para transformar as respostas em comentários)\ncreate table public.comment_mail_threads (\n  id uuid primary key default gen_random_uuid(),\n  organization_id uuid not null references public.organizations (id) on delete cascade,\n  event_id uuid not null references public.events (id) on delete cascade,\n  connection_id uuid references public.calendar_connections (id) on delete cascade,\n  thread_id text not null,\n  created_at timestamptz not null default now(),\n  unique (connection_id, thread_id)\n);\ncreate index comment_mail_threads_event_idx on public.comment_mail_threads (event_id);\nalter table public.comment_mail_threads enable row level security;\ncreate policy \"conversas de comentários: membros leem\" on public.comment_mail_threads for select using (public.is_member(organization_id));\n\n-- Reenvia (em silêncio) os compromissos com convidados, para que passem a levar os dados\n-- compartilhados do Lex e a permissão de alteração pelos convidados\nupdate public.events\n   set updated_at = now()\n where source in ('lex', 'ai') and deleted_at is null and ends_at > now() - interval '7 days'\n   and attendees is not null and attendees <> '[]'::jsonb;\n" },
  { name: "20261010000022_sync_orphan_duplicates.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Cópias criadas por duas sincronizações simultâneas\n-- Ao conectar o calendário, a primeira importação e a sincronização automática podiam\n-- rodar ao mesmo tempo e cada uma criava o mesmo compromisso; só uma das cópias ficava\n-- vinculada ao calendário externo. Remove a cópia sem vínculo (ela veio do mesmo evento\n-- externo, então não tem dado próprio do Lex).\n-- ════════════════════════════════════════════════════════════════════════════\n\nupdate public.events e\nset deleted_at = now()\nwhere e.deleted_at is null\n  and e.source not in ('lex', 'ai')\n  and e.client_id is null\n  and e.process_id is null\n  and not exists (select 1 from public.event_external_links l where l.event_id = e.id)\n  and exists (\n    select 1\n    from public.events k\n    join public.event_external_links kl on kl.event_id = k.id\n    where k.id <> e.id\n      and k.organization_id = e.organization_id\n      and k.deleted_at is null\n      and k.source = e.source\n      and k.title = e.title\n      and k.starts_at = e.starts_at\n      and k.ends_at = e.ends_at\n  );\n" },
  { name: "20261012000023_ai_settings.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Agente de inteligência artificial\n-- Cada escritório escolhe a IA que o Lex usa: a gratuita no computador (Ollama), serviços\n-- com plano gratuito (Groq, Gemini, OpenRouter) ou a própria conta de ChatGPT, Claude ou\n-- Copilot. A chave fica criptografada e nunca é lida pelo navegador.\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate table public.ai_settings (\n  organization_id uuid primary key references public.organizations (id) on delete cascade,\n  provider text not null default 'ollama',\n  model text,\n  base_url text,\n  api_key_enc text,\n  last_test_at timestamptz,\n  last_error text,\n  updated_by uuid references auth.users (id) on delete set null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate trigger set_updated_at before update on public.ai_settings\n  for each row execute function public.set_updated_at();\n\nalter table public.ai_settings enable row level security;\ncreate policy \"agente de IA: membros leem\" on public.ai_settings for select using (public.is_member(organization_id));\nrevoke select, insert, update on public.ai_settings from authenticated, anon;\ngrant select (organization_id, provider, model, base_url, last_test_at, last_error, updated_at)\n  on public.ai_settings to authenticated;\n" },
  { name: "20261012000024_licensing.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — Assinantes\n-- Tabelas do servidor de assinaturas (a instalação na nuvem do titular do Lex): contas dos\n-- assinantes, códigos de entrada por e-mail e sessões dos aplicativos. Nas instalações\n-- no computador elas ficam vazias. Só o servidor (service role) lê e grava.\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate table public.license_accounts (\n  id uuid primary key default gen_random_uuid(),\n  email text not null unique,\n  name text,\n  document text,\n  status text not null default 'trial' check (status in ('trial', 'active', 'overdue', 'canceled')),\n  trial_ends_at timestamptz not null,\n  paid_until timestamptz,\n  asaas_customer_id text,\n  asaas_subscription_id text,\n  last_seen_at timestamptz,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table public.license_codes (\n  email text primary key,\n  code_hash text not null,\n  expires_at timestamptz not null,\n  attempts integer not null default 0,\n  sent_at timestamptz not null default now()\n);\n\ncreate table public.license_sessions (\n  token_hash text primary key,\n  account_id uuid not null references public.license_accounts (id) on delete cascade,\n  device text,\n  created_at timestamptz not null default now(),\n  last_seen_at timestamptz not null default now()\n);\ncreate index license_sessions_account_idx on public.license_sessions (account_id);\n\ncreate trigger set_updated_at before update on public.license_accounts\n  for each row execute function public.set_updated_at();\n\nalter table public.license_accounts enable row level security;\nalter table public.license_codes enable row level security;\nalter table public.license_sessions enable row level security;\nrevoke all on public.license_accounts, public.license_codes, public.license_sessions from anon, authenticated;\n" },
  { name: "20261015000025_merge_duplicates_tolerant.sql", sql: "-- ════════════════════════════════════════════════════════════════════════════\n-- Lex Calendário — União de duplicados mais tolerante\n-- Ao restaurar um backup depois de conectar o Google, a cópia do backup e a trazida do\n-- Google podiam ficar com término diferente (ex.: dia inteiro terminando 23:59 ou 00:00,\n-- ou horário alterado no Google depois do backup) e não eram unidas. Agora a cópia antiga\n-- sem vínculo de um evento do calendário externo é unida mesmo com término diferente.\n-- ════════════════════════════════════════════════════════════════════════════\n\ncreate or replace function public.merge_duplicate_events(org uuid default null)\nreturns integer language plpgsql security definer set search_path = '' as $$\ndeclare\n  g record;\n  keeper uuid;\n  loser uuid;\n  merged integer := 0;\nbegin\n  for g in\n    select array_agg(e.id order by (\n             (e.client_id is not null)::int * 4\n           + (e.process_id is not null)::int * 4\n           + (select count(*) from public.event_checklist_items c where c.event_id = e.id)::int\n           + 2 * (select count(*) from public.event_comments c where c.event_id = e.id)::int\n           + 2 * (select count(*) from public.event_attachments c where c.event_id = e.id)::int\n           + 3 * (e.source in ('lex', 'ai'))::int\n           + 2 * (exists (select 1 from public.event_external_links l where l.event_id = e.id))::int\n         ) desc, e.created_at) as ids\n    from public.events e\n    where e.deleted_at is null\n      and (org is null or e.organization_id = org)\n    group by e.organization_id,\n             regexp_replace(lower(btrim(e.title)), '^\\s*(✔️|✔|✅)\\s*', ''),\n             e.starts_at\n    having count(*) > 1\n  loop\n    keeper := g.ids[1];\n    foreach loser in array g.ids[2:array_length(g.ids, 1)]\n    loop\n      -- Término diferente: só une a cópia antiga de um evento do calendário externo (sem vínculo),\n      -- por exemplo a que veio de um backup quando o mesmo evento já foi trazido do Google.\n      if exists (\n        select 1 from public.events l, public.events k\n        where l.id = loser and k.id = keeper\n          and l.ends_at is distinct from k.ends_at\n          and (\n            l.source in ('lex', 'ai')\n            or exists (select 1 from public.event_external_links x where x.event_id = loser)\n          )\n      ) then\n        continue;\n      end if;\n      -- Cópia ligada a outro evento do Google na mesma conta: o Google também tem a cópia.\n      -- Só é apagada (no Lex e, pela sincronização, no Google) se tiver o mesmo nome, horário e local\n      -- e nenhum dado do Lex (cliente, processo, checklist, comentários, anexos).\n      if exists (\n        select 1 from public.event_external_links a\n        join public.event_external_links b on b.connection_id = a.connection_id\n        where a.event_id = loser and b.event_id = keeper\n      ) then\n        if exists (\n          select 1 from public.events l, public.events k\n          where l.id = loser and k.id = keeper\n            and l.client_id is null and l.process_id is null and l.collaborator_id is null\n            and l.location is not distinct from k.location\n            and not exists (select 1 from public.event_checklist_items c where c.event_id = loser)\n            and not exists (select 1 from public.event_comments c where c.event_id = loser)\n            and not exists (select 1 from public.event_attachments c where c.event_id = loser)\n        ) then\n          update public.events set deleted_at = now() where id = loser;\n          merged := merged + 1;\n        end if;\n        continue;\n      end if;\n      update public.event_external_links set event_id = keeper where event_id = loser;\n\n      update public.events k set\n        client_id = coalesce(k.client_id, l.client_id),\n        process_id = coalesce(k.process_id, l.process_id),\n        tribunal = coalesce(k.tribunal, l.tribunal),\n        court_division = coalesce(k.court_division, l.court_division),\n        description_text = coalesce(k.description_text, l.description_text),\n        description = coalesce(k.description, l.description),\n        collaborator_id = coalesce(k.collaborator_id, l.collaborator_id),\n        related_event_id = coalesce(k.related_event_id, nullif(l.related_event_id, k.id))\n      from public.events l\n      where k.id = keeper and l.id = loser;\n\n      if not exists (select 1 from public.event_checklist_items where event_id = keeper) then\n        update public.event_checklist_items set event_id = keeper where event_id = loser;\n      end if;\n      update public.event_comments set event_id = keeper where event_id = loser;\n      update public.event_attachments set event_id = keeper where event_id = loser;\n      update public.events set related_event_id = keeper where related_event_id = loser;\n      update public.communications set event_id = keeper where event_id = loser;\n\n      update public.events set deleted_at = now() where id = loser;\n      merged := merged + 1;\n    end loop;\n  end loop;\n  return merged;\nend $$;\nrevoke execute on function public.merge_duplicate_events(uuid) from public, anon, authenticated;\n\n-- Une agora as cópias que ficaram duplicadas nas instalações existentes\nselect public.merge_duplicate_events(null);\n" },
];
